// POST /wrench: a rider pressed the wrench button in the app to report a broken bike.
import type { Database } from "bun:sqlite";
import { logEvent } from "./log";

type WrenchReport = { bike_id?: string; fault?: string };
type BikeRow = { bike_id: string; station_id: string };
type StationRow = { depot: string };

export function recordWrench(database: Database, report: WrenchReport) {
  const bike = database.query("SELECT * FROM bikes WHERE bike_id = ?").get(report.bike_id ?? "");
  if (!bike) return { status: 404, body: { error: `no bike called ${report.bike_id}` } };
  const { bike_id, station_id } = bike as BikeRow;
  const station = database.query("SELECT depot FROM stations WHERE station_id = ?").get(station_id);
  const reportedAt = new Date().toISOString();
  const fault = report.fault ?? "OTHER";

  database
    .query("INSERT INTO wrenches (bike_id, station_id, fault, reported_at) VALUES (?, ?, ?, ?)")
    .run(bike_id, station_id, fault, reportedAt);

  // A dispatcher opens the repair job from the wrench.
  const jobId = `J-${Date.now()}`;
  const depot = (station as StationRow).depot;
  database
    .query("INSERT INTO repair_jobs VALUES (?, ?, ?, ?, 'wrench', ?, ?, ?, NULL)")
    .run(jobId, bike_id, station_id, depot, fault, reportedAt, reportedAt);

  logEvent("wrench", { bike_id, station_id, fault, job_id: jobId });
  return { status: 201, body: { job_id: jobId, bike_id } };
}
// GET /crew/queue?depot=North: the open repair jobs a depot's crews work through, top first.
import type { Database } from "bun:sqlite";

const HOUR = 60 * 60 * 1000;

type JobRow = {
  job_id: string;
  bike_id: string;
  station_id: string;
  source: string;
  fault: string;
  reported_at: string;
  opened_at: string;
};

// The contract limit: 48 hours for a wrench, 96 hours for a defect a crew found itself.
// The clock runs from when the dispatch desk opened the job.
function contractDeadline(job: JobRow): string {
  const limitHours = job.source === "wrench" ? 48 : 96;
  return new Date(Date.parse(job.opened_at) + limitHours * HOUR).toISOString();
}

export function crewQueue(database: Database, depot: string | null) {
  const jobs = database
    .query("SELECT * FROM repair_jobs WHERE closed_at IS NULL AND (?1 IS NULL OR depot = ?1)")
    .all(depot) as JobRow[];
  // Oldest job first, the way the dispatch desk has always worked.
  jobs.sort((first, second) => first.opened_at.localeCompare(second.opened_at));
  const queue = jobs.map((job) => ({ ...job, deadline: contractDeadline(job) }));
  return { depot: depot ?? "all", jobs: queue };
}
// GET /: a map of Brannock's stations. A red number is how many broken bikes wait at a station.
import type { Database } from "bun:sqlite";
import { stationStatus } from "./feed";

type StationRow = { station_id: string; name: string; district: string; x: number; y: number };

const DISTRICT_COLOURS: Record<string, string> = {
  North: "#3b82f6",
  East: "#14b8a6",
  Centre: "#a855f7",
  South: "#f59e0b",
  West: "#22c55e",
};

function stationDot(station: StationRow, brokenBikes: number): string {
  const colour = DISTRICT_COLOURS[station.district] ?? "#888";
  const dot = `<circle cx="${station.x}" cy="${station.y}" r="9" fill="${colour}">`;
  const title = `<title>${station.station_id} ${station.name}</title></circle>`;
  if (brokenBikes === 0) return dot + title;
  const badge = `<circle cx="${station.x + 9}" cy="${station.y - 9}" r="8" fill="#dc2626"/>`;
  const count = `<text x="${station.x + 9}" y="${station.y - 5}">${brokenBikes}</text>`;
  return dot + title + badge + count;
}

function legend(totalBroken: number, totalAvailable: number): string {
  const districts = Object.entries(DISTRICT_COLOURS)
    .map(([name, colour]) => `<span><i style="background:${colour}"></i>${name}</span>`)
    .join("");
  return `<p class="legend">${districts}</p>
    <p><b>${totalAvailable}</b> bikes riders can rent. <b class="red">${totalBroken}</b> broken
    bikes out of service. Red numbers show broken bikes waiting at a station.</p>`;
}

const STYLE = `body{font-family:system-ui,sans-serif;margin:24px;background:#f8fafc;color:#0f172a}
  h1{margin:0 0 4px}svg{background:#fff;border:1px solid #cbd5e1;border-radius:8px}
  text{font-size:10px;fill:#fff;text-anchor:middle;font-weight:700}
  .legend span{margin-right:14px}.legend i{display:inline-block;width:10px;height:10px;
  border-radius:50%;margin-right:4px}.red{color:#dc2626}`;

export function mapPage(database: Database): string {
  const stations = database.query("SELECT * FROM stations").all() as StationRow[];
  const feed = stationStatus(database).data.stations;
  const brokenAt = new Map(feed.map((entry) => [entry.station_id, entry.num_vehicles_disabled]));
  const dots = stations.map((station) =>
    stationDot(station, brokenAt.get(station.station_id) ?? 0),
  );
  const totalBroken = feed.reduce((sum, entry) => sum + entry.num_vehicles_disabled, 0);
  const totalAvailable = feed.reduce((sum, entry) => sum + entry.num_vehicles_available, 0);
  return `<!doctype html><html><head><meta charset="utf-8"><title>Kestrel Bike Share</title>
    <style>${STYLE}</style></head><body><h1>Kestrel Bike Share: Brannock</h1>
    ${legend(totalBroken, totalAvailable)}
    <svg width="940" height="660" viewBox="0 0 940 660">${dots.join("")}</svg></body></html>`;
}
// AC-2: the wrench, the repair job and the disabled flag are recorded together, or not at all.
import { expect, test } from "bun:test";
import { countRows, isDisabledInTable, openDatabase, recordWrench } from "./helpers";

const db = openDatabase();

test("AC-2 (a): a 201 adds 1 wrench, 1 open wrench job, and disables the bike", () => {
  const BIKE = "B-1001";
  const wrenchesBefore = countRows(db, "wrenches", BIKE);
  const jobsBefore = countRows(db, "repair_jobs", BIKE);

  expect(recordWrench(db, { bike_id: BIKE, fault: "CHAIN" }).status).toBe(201);

  expect(countRows(db, "wrenches", BIKE) - wrenchesBefore).toBe(1);
  expect(countRows(db, "repair_jobs", BIKE) - jobsBefore).toBe(1);
  const openWrenchJobs = db
    .query(
      "SELECT COUNT(*) AS n FROM repair_jobs WHERE bike_id = ? AND source = 'wrench' AND closed_at IS NULL",
    )
    .get(BIKE) as { n: number };
  expect(openWrenchJobs.n).toBe(1);
  expect(isDisabledInTable(db, BIKE)).toBe(1);
});

// Forces one of the three writes to fail with a TEMP trigger, then checks nothing is kept.
function expectRollback(bike: string, triggerSql: string) {
  const wrenchesBefore = countRows(db, "wrenches", bike);
  const jobsBefore = countRows(db, "repair_jobs", bike);
  db.exec(triggerSql);
  try {
    expect(() => recordWrench(db, { bike_id: bike, fault: "TYRE" })).toThrow();
  } finally {
    db.exec("DROP TRIGGER IF EXISTS ac2_fail");
  }
  expect(countRows(db, "wrenches", bike) - wrenchesBefore).toBe(0);
  expect(countRows(db, "repair_jobs", bike) - jobsBefore).toBe(0);
  expect(isDisabledInTable(db, bike)).toBe(0);
}

test("AC-2 (b): if disabling the bike fails, no wrench or job row is kept", () => {
  expectRollback(
    "B-1002",
    `CREATE TEMP TRIGGER ac2_fail BEFORE UPDATE ON bikes
     BEGIN SELECT RAISE(ABORT, 'ac2: forced bikes update failure'); END`,
  );
});

test("AC-2 (c): if inserting the repair job fails, no wrench row is kept", () => {
  expectRollback(
    "B-1003",
    `CREATE TEMP TRIGGER ac2_fail BEFORE INSERT ON repair_jobs
     BEGIN SELECT RAISE(ABORT, 'ac2: forced repair_jobs insert failure'); END`,
  );
});
// AC-5: after a wrench, the map at / shows station S with the same counts as station_status.json.
import { expect, test } from "bun:test";
import { mapPage, openDatabase, recordWrench, stationCounts, stationOf } from "./helpers";

const db = openDatabase();
const BIKE = "B-1006";

// The SVG for one station: the text of its <title>, and the red badge number if it has one.
function stationOnMap(html: string, stationId: string) {
  const pattern = new RegExp(
    `<title>(${stationId}\\b[^<]*)</title></circle>(?:<circle[^>]*/><text[^>]*>(\\d+)</text>)?`,
  );
  const match = html.match(pattern);
  if (!match) throw new Error(`station ${stationId} not found on the map`);
  return { title: match[1], badge: match[2] === undefined ? 0 : Number(match[2]) };
}

test("AC-5: the map's available and disabled numbers for S equal station_status", () => {
  const station = stationOf(db, BIKE);
  const before = stationCounts(db, station);
  expect(recordWrench(db, { bike_id: BIKE, fault: "BRAKE" }).status).toBe(201);

  const feed = stationCounts(db, station);
  const onMap = stationOnMap(mapPage(db), station);

  expect(onMap.title.match(/(\d+) available/)?.[1]).toBe(String(feed.available));
  expect(onMap.title.match(/(\d+) disabled/)?.[1]).toBe(String(feed.disabled));
  expect(onMap.badge).toBe(feed.disabled);
  expect(onMap.badge).toBe(before.disabled + 1); // the badge has to move, not just match
});
// Shared setup for the acceptance tests in this folder. Not a test file.
// src/database reads SPOKE_DB and src/log reads SPOKE_LOG when they load, so the paths are set
// to temp files here, before either module is imported (AGENTS.md). Every src/ import below is
// dynamic on purpose: a static `import ... from "../../src/..."` would be hoisted above these lines.
import type { Database } from "bun:sqlite";
import { expect } from "bun:test";
import { tmpdir } from "node:os";
import { join } from "node:path";

const runId = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
process.env.SPOKE_DB = join(tmpdir(), `spoke-acceptance-${runId}.db`);
process.env.SPOKE_LOG = join(tmpdir(), `spoke-acceptance-${runId}.log`);

const database = await import("../../src/database");
const feed = await import("../../src/feed");
const wrenches = await import("../../src/wrenches");
const map = await import("../../src/map-page");
const queue = await import("../../src/crew-queue");
const csv = await import("../../src/csv");

export const openDatabase = database.openDatabase;
export const recordWrench = wrenches.recordWrench;
export const stationStatus = feed.stationStatus;
export const vehicleStatus = feed.vehicleStatus;
export const mapPage = map.mapPage;
export const crewQueue = queue.crewQueue;
export const readCsv = csv.readCsv;

export const HOUR = 60 * 60 * 1000;

export type QueueJob = {
  job_id: string;
  depot: string;
  source: string;
  reported_at: string;
  opened_at: string;
  deadline: string;
};

/** The station a bike is docked at, from the `bikes` table. */
export function stationOf(db: Database, bikeId: string): string {
  const row = db.query("SELECT station_id FROM bikes WHERE bike_id = ?").get(bikeId) as {
    station_id: string;
  } | null;
  if (!row) throw new Error(`test setup: no bike ${bikeId}`);
  return row.station_id;
}

/** How many rows in `table` belong to `bikeId`. */
export function countRows(db: Database, table: "wrenches" | "repair_jobs", bikeId: string): number {
  const row = db.query(`SELECT COUNT(*) AS n FROM ${table} WHERE bike_id = ?`).get(bikeId) as {
    n: number;
  };
  return row.n;
}

/** The bike's `is_disabled` column (0 or 1). */
export function isDisabledInTable(db: Database, bikeId: string): number {
  const row = db.query("SELECT is_disabled FROM bikes WHERE bike_id = ?").get(bikeId) as {
    is_disabled: number;
  };
  return row.is_disabled;
}

/** Station S's entry in `station_status.json`, read through `stationStatus`. */
export function stationCounts(db: Database, stationId: string) {
  const entry = feed.stationStatus(db).data.stations.find((s) => s.station_id === stationId);
  if (!entry) throw new Error(`test setup: no station ${stationId} in station_status`);
  return {
    available: entry.num_vehicles_available,
    disabled: entry.num_vehicles_disabled,
    docks: entry.num_docks_available,
  };
}

/** SLA-4: the deadline counts from `reported_at`, 48h for a wrench, 96h for anything else. */
export function contractDeadline(job: { source: string; reported_at: string }): string {
  const limitHours = job.source === "wrench" ? 48 : 96;
  return new Date(Date.parse(job.reported_at) + limitHours * HOUR).toISOString();
}

/** AC-9 order: deadline ascending, then reported_at, then job_id. */
export function compareQueueOrder(a: QueueJob, b: QueueJob): number {
  return (
    a.deadline.localeCompare(b.deadline) ||
    a.reported_at.localeCompare(b.reported_at) ||
    a.job_id.localeCompare(b.job_id)
  );
}

/** Asserts that `jobs` is already in AC-9 order. Compares job ids so a failure is readable. */
export function expectQueueOrder(jobs: QueueJob[]) {
  const sorted = [...jobs].sort(compareQueueOrder);
  expect(jobs.map((job) => job.job_id)).toEqual(sorted.map((job) => job.job_id));
}

/** Asserts that every job's deadline follows SLA-4 (AC-8). */
export function expectContractDeadlines(jobs: QueueJob[]) {
  const wrong = jobs
    .filter((job) => job.deadline !== contractDeadline(job))
    .map((job) => `${job.job_id}: got ${job.deadline}, want ${contractDeadline(job)}`);
  expect(wrong).toEqual([]);
}

/** Inserts an open repair job straight into the table, for queue tests. */
export function insertJob(
  db: Database,
  job: { job_id: string; bike_id: string; station_id: string; depot: string; source: string; reported_at: string; opened_at: string },
) {
  db.query("INSERT INTO repair_jobs VALUES (?, ?, ?, ?, ?, 'OTHER', ?, ?, NULL)").run(
    job.job_id,
    job.bike_id,
    job.station_id,
    job.depot,
    job.source,
    job.reported_at,
    job.opened_at,
  );
}

